Here's a complete implementation:

**XAML — `ItemsPage.xaml`**

```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             xmlns:vm="clr-namespace:MyApp.ViewModels"
             xmlns:models="clr-namespace:MyApp.Models"
             x:Class="MyApp.Views.ItemsPage"
             x:DataType="vm:ItemsViewModel">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">
        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding CurrentItem, Mode=TwoWay}"
                        SelectionChangedCommand="{Binding ItemSelectedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate x:DataType="models:Item">
                    <Grid Padding="12" ColumnDefinitions="48,*" ColumnSpacing="12">
                        <Image Source="{Binding Icon}" WidthRequest="40" HeightRequest="40" />
                        <Label Grid.Column="1" Text="{Binding Name}" VerticalOptions="Center" />
                    </Grid>
                </DataTemplate>
            </CollectionView.ItemTemplate>
            <CollectionView.EmptyView>
                <ContentView>
                    <Label Text="No items found."
                           HorizontalOptions="Center" VerticalOptions="Center" />
                </ContentView>
            </CollectionView.EmptyView>
        </CollectionView>
    </RefreshView>
</ContentPage>
```

**ViewModel — `ItemsViewModel.cs`**

```csharp
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using System.Collections.ObjectModel;

namespace MyApp.ViewModels;

public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;

    public ItemsViewModel(IApiService api)
    {
        _api = api;
    }

    public ObservableCollection<Item> Items { get; } = new();

    [ObservableProperty]
    private Item? currentItem;

    [ObservableProperty]
    private bool isRefreshing;

    [RelayCommand]
    private async Task ItemSelectedAsync()
    {
        if (CurrentItem is null) return;

        await Shell.Current.GoToAsync($"detail?id={CurrentItem.Id}");

        // Clear selection so the user can re-select the same item later
        CurrentItem = null;
    }

    [RelayCommand]
    private async Task RefreshAsync()
    {
        try
        {
            var data = await _api.GetItemsAsync();
            Items.Clear();
            foreach (var item in data)
                Items.Add(item);
        }
        finally
        {
            IsRefreshing = false; // Stops the refresh spinner
        }
    }
}
```

**Key bindings explained:**

| XAML property | ViewModel property | Why |
|---|---|---|
| `IsRefreshing` | `IsRefreshing` (bool) | Two-way — `RefreshView` sets it `true` on pull; you set it `false` when done |
| `Command` on RefreshView | `RefreshCommand` | Auto-generated by `[RelayCommand]` on `RefreshAsync` |
| `SelectedItem` | `CurrentItem` (TwoWay) | Tracks which item the user tapped |
| `SelectionChangedCommand` | `ItemSelectedCommand` | Fires on selection change → navigates to detail page |
| `ItemsSource` | `Items` (ObservableCollection) | Use `ObservableCollection<T>` so adds/removes update the UI automatically |

**Important details:**
- **Set `IsRefreshing = false`** in a `finally` block — otherwise the spinner never stops on errors.
- **Clear `CurrentItem` after navigation** — without this, tapping the same item twice won't trigger `SelectionChangedCommand` a second time.
- **Always use `x:DataType`** on both the page and the `DataTemplate` for compiled bindings.
- **Never use `ViewCell`** — `CollectionView` templates use plain views like `Grid` directly.
